* {box-sizing: border-box;}
body {margin: 0;}
.app {min-height: 100vh; background: color-mix(in srgb, var(--g-color-base-generic) 36%, var(--g-color-base-background)); color: var(--g-color-text-primary);}
.page-header {height: 72px; border-bottom: 1px solid var(--g-color-line-generic); background: var(--g-color-base-background);}
.header-inner {height: 100%; max-width: 1512px; margin: auto; padding: 0 var(--g-spacing-8); display: flex; align-items: center; gap: var(--g-spacing-6);}
.brand {display: flex; align-items: center; font-size: 27px; font-weight: 750; letter-spacing: -1.4px; flex-shrink: 0;}
.brand-dot {color: var(--app-accent);}
.brand-mark {width: 28px; height: 28px; position: relative; margin-right: var(--g-spacing-2); display: flex; align-items: center; gap: 3px; transform: rotate(-12deg);}
.brand-mark span {display: block; width: 7px; height: 24px; background: var(--app-accent); border-radius: var(--g-border-radius-s);}
.brand-mark span:first-child {height: 16px; align-self: flex-end;}
.brand-mark span:last-child {height: 16px; align-self: flex-start;}
.header-divider {height: 24px; width: 1px; background: var(--g-color-line-generic); flex-shrink: 0;}
.breadcrumb {display: flex; align-items: center; gap: var(--g-spacing-4); color: var(--g-color-text-secondary); font-size: 13px; min-width: 0;}
.breadcrumb-current {color: var(--g-color-text-primary);}
.header-right {display: flex; align-items: center; margin-left: auto; gap: var(--g-spacing-4); flex-shrink: 0;}
.profile-avatar {width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--g-color-base-neutral-light); font-size: 11px; font-weight: 600; border: 3px solid var(--g-color-base-background); outline: 1px solid var(--g-color-line-generic);}
.workspace {max-width: 1376px; padding: var(--g-spacing-9) var(--g-spacing-8) var(--g-spacing-6); margin: auto;}
.page-title-row {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-5); margin-bottom: var(--g-spacing-7);}
.title-with-label {display: flex; align-items: center; gap: var(--g-spacing-3);}
.title-with-label > .g-text {font-weight: 650; letter-spacing: -0.8px;}
.workspace-label {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-s); padding: var(--g-spacing-1) var(--g-spacing-2); color: var(--g-color-text-secondary); font-size: 11px; background: var(--g-color-base-background);}
.page-description {color: var(--g-color-text-secondary); margin: var(--g-spacing-2) 0 0; font-size: 14px;}
.page-actions {display: flex; gap: var(--g-spacing-3); flex-shrink: 0;}
.page-actions .g-button {--g-button-border-radius: var(--g-border-radius-m); font-weight: 500;}
.stats-grid {display: grid; grid-template-columns: 1fr 1fr 1fr 1.18fr; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-7);}
.stat-card {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-5);}
.stat-top {display: flex; align-items: center; justify-content: space-between; color: var(--g-color-text-secondary); font-size: 13px; gap: var(--g-spacing-3);}
.stat-top svg {color: var(--g-color-text-hint);}
.stat-bottom {display: flex; align-items: baseline; gap: var(--g-spacing-3); margin-top: var(--g-spacing-4);}
.stat-bottom > .g-text {letter-spacing: -0.9px; font-weight: 600; white-space: nowrap;}
.stat-caption {font-size: 11px; color: var(--g-color-text-hint);}
.stat-trend {display: inline-flex; align-items: center; gap: var(--g-spacing-1); padding: var(--g-spacing-1) var(--g-spacing-2); font-size: 10px; color: var(--g-color-text-positive-heavy); background: var(--g-color-base-positive-light); border-radius: var(--g-border-radius-s); white-space: nowrap;}
.revenue-icon {color: var(--app-accent); margin-left: auto;}
.table-card {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); overflow: hidden; box-shadow: 0 2px 4px color-mix(in srgb, var(--g-color-sfx-shadow) 6%, transparent);}
.table-tabs {display: flex; align-items: center; gap: var(--g-spacing-4); padding: 0 var(--g-spacing-5); border-bottom: 1px solid var(--g-color-line-generic); min-height: 58px;}
.table-tab.g-button {height: 58px; border-bottom: 2px solid transparent; --g-button-border-radius: 0; --g-button-text-color: var(--g-color-text-secondary); --g-button-padding: 4px; font-weight: 500;}
.table-tab-active.g-button {border-bottom-color: var(--app-accent); --g-button-text-color: var(--app-accent);}
.tab-count {font-size: 10px; margin-left: var(--g-spacing-2); background: var(--g-color-base-generic); border-radius: var(--g-border-radius-s); padding: 2px 6px; color: var(--g-color-text-secondary);}
.table-tab-active .tab-count {background: var(--g-color-base-selection); color: var(--app-accent);}
.table-live {display: flex; gap: var(--g-spacing-2); align-items: center; margin-left: auto; color: var(--g-color-text-secondary); font-size: 11px; white-space: nowrap;}
.table-live .status-dot {background: var(--g-color-text-positive); width: 6px; height: 6px;}
.table-toolbar {padding: var(--g-spacing-5); display: flex; align-items: center; gap: var(--g-spacing-4); justify-content: space-between;}
.search-input {width: 360px; --g-text-input-border-radius: var(--g-border-radius-m);}
.search-input svg {color: var(--g-color-text-hint); margin-left: var(--g-spacing-1);}
.filter-controls {display: flex; align-items: center; gap: var(--g-spacing-2); flex-shrink: 0;}
.filter-controls .g-select {min-width: 132px;}
.filter-icon {display: grid; place-items: center; width: 36px; height: 36px; color: var(--g-color-text-secondary); border-left: 1px solid var(--g-color-line-generic); margin-left: var(--g-spacing-1); padding-left: var(--g-spacing-2);}
.table-container {overflow-x: auto; max-width: 100%;}
.clients-table {min-width: 1000px; font-size: 13px;}
/* UIKit 7.43.0 has no cell spacing/header surface CSS API. Scoped internal-class customization; replace if upstream exposes tokens. */
.clients-table .g-table__head {background: color-mix(in srgb, var(--g-color-base-generic) 45%, var(--g-color-base-background)); color: var(--g-color-text-secondary);}
.clients-table .g-table__head .g-table__cell {font-size: 11px; font-weight: 500; padding-top: var(--g-spacing-3); padding-bottom: var(--g-spacing-3); border-top: 1px solid var(--g-color-line-generic);}
.clients-table .g-table__body .g-table__cell {padding-top: var(--g-spacing-3); padding-bottom: var(--g-spacing-3);}
.clients-table .g-table__cell:first-child {padding-left: var(--g-spacing-5); padding-right: var(--g-spacing-3);}
.clients-table .g-table__cell:last-child {padding-right: var(--g-spacing-4);}
.clients-table .g-table__sort-indicator {opacity: 0.45;}
.clients-table .g-table__sort_active {color: var(--g-color-text-primary);}
.client-cell {display: flex; align-items: center; gap: var(--g-spacing-3);}
.avatar {display: grid; place-items: center; flex-shrink: 0; width: 34px; height: 34px; border-radius: 50%; font-size: 11px; font-weight: 550;}
.avatar-0 {background: var(--g-color-base-utility-light); color: var(--g-color-text-utility);}
.avatar-1 {background: var(--g-color-base-info-light); color: var(--g-color-text-info);}
.avatar-2 {background: var(--g-color-base-warning-light); color: var(--g-color-text-warning-heavy);}
.avatar-3 {background: var(--g-color-base-positive-light); color: var(--g-color-text-positive-heavy);}
.avatar-4 {background: var(--g-color-base-danger-light); color: var(--g-color-text-danger);}
.avatar-5 {background: var(--g-color-base-misc-light); color: var(--g-color-text-misc);}
.client-info {display: flex; flex-direction: column; gap: var(--g-spacing-1); min-width: 0;}
.client-name {font-size: 12px; font-weight: 550;}
.client-email {font-size: 11px; color: var(--g-color-text-secondary);}
.company-cell {font-size: 12px;}
.status {display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px; border-radius: var(--g-border-radius-xl); font-size: 10px; font-weight: 500;}
.status-dot {width: 5px; height: 5px; background: currentColor; border-radius: 50%; display: inline-block; flex-shrink: 0;}
.status-active {background: var(--g-color-base-positive-light); color: var(--g-color-text-positive-heavy);}
.status-trial {background: var(--g-color-base-warning-light); color: var(--g-color-text-warning-heavy);}
.status-archived {background: var(--g-color-base-generic); color: var(--g-color-text-secondary);}
.plan {font-size: 10px; border: 1px solid var(--g-color-line-generic); padding: 3px 7px; border-radius: var(--g-border-radius-s);}
.plan-business {background: var(--g-color-base-utility-light); color: var(--g-color-text-utility); border-color: color-mix(in srgb, var(--g-color-text-utility) 18%, transparent);}
.plan-pro {background: var(--g-color-base-info-light); color: var(--g-color-text-info); border-color: color-mix(in srgb, var(--g-color-text-info) 18%, transparent);}
.plan-basic {color: var(--g-color-text-secondary);}
.date-cell {color: var(--g-color-text-secondary); font-size: 11px;}
.revenue-cell {font-size: 12px; font-variant-numeric: tabular-nums; font-weight: 500;}
.muted {color: var(--g-color-text-secondary);}
.selection-bar {display: flex; gap: var(--g-spacing-3); align-items: center; padding: var(--g-spacing-3) var(--g-spacing-5); background: var(--g-color-base-selection); color: var(--app-accent); font-size: 12px; border-top: 1px solid var(--g-color-line-generic);}
.selection-bar > span {margin-right: auto;}
.table-footer {display: flex; justify-content: space-between; align-items: center; padding: var(--g-spacing-4) var(--g-spacing-5); border-top: 1px solid var(--g-color-line-generic); gap: var(--g-spacing-4);}
.page-size {display: flex; align-items: center; gap: var(--g-spacing-3); color: var(--g-color-text-secondary); font-size: 11px;}
.rows-summary {margin-left: var(--g-spacing-3);}
.workspace-footer {display: flex; justify-content: space-between; gap: var(--g-spacing-4); margin-top: var(--g-spacing-5); font-size: 10px; color: var(--g-color-text-hint);}
.workspace-footer > span:first-child {display: flex; align-items: center; gap: var(--g-spacing-2);}
.empty-actions {padding: var(--g-spacing-5); text-align: center;}
.notice {position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: var(--g-spacing-3); background: var(--g-color-base-background); padding: var(--g-spacing-3) var(--g-spacing-4); border: 1px solid var(--g-color-line-positive); border-radius: var(--g-border-radius-l); box-shadow: 0 4px 24px var(--g-color-sfx-shadow); z-index: 10; max-width: calc(100vw - 32px);}
.notice > svg {color: var(--app-accent); flex-shrink: 0;}
.dialog {width: min(460px, calc(100vw - 32px)); padding: var(--g-spacing-7);}
.dialog-header {display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-4);}
.form-field {display: flex; flex-direction: column; gap: var(--g-spacing-2); margin-top: var(--g-spacing-4); font-size: 13px;}
.dialog-actions {display: flex; justify-content: flex-end; gap: var(--g-spacing-3); margin-top: var(--g-spacing-6);}
.form-error {color: var(--g-color-text-danger);}
.help-content {line-height: 1.6; margin-bottom: var(--g-spacing-5);}
.detail-identity {display: flex; align-items: center; gap: var(--g-spacing-3); margin: var(--g-spacing-5) 0;}
.detail-list {display: grid; grid-template-columns: 1fr 1.3fr; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-6);}
.detail-list dt {color: var(--g-color-text-secondary);}
.detail-list dd {margin: 0; overflow-wrap: anywhere;}
a {color: var(--g-color-text-link);}
@media (min-width: 1500px) {.workspace {padding-top: var(--g-spacing-10);}}
@media (max-width: 1000px) {
  .workspace {padding: var(--g-spacing-6);}
  .workspace-label {display: none;}
  .stats-grid {grid-template-columns: repeat(2, 1fr);}
  .table-live {display: none;}
  .stat-bottom {justify-content: space-between;}
  .workspace-footer > span:last-child {display: none;}
}
@media (max-width: 600px) {
  .page-header {height: 60px;}
  .header-inner {padding: 0 var(--g-spacing-4); gap: var(--g-spacing-4);}
  .breadcrumb {font-size: 12px;}
  .breadcrumb > span:first-child, .breadcrumb > svg {display: none;}
  .header-right {gap: var(--g-spacing-2);}
  .header-right .header-divider {display: none;}
  .workspace {padding: var(--g-spacing-5) var(--g-spacing-3);}
  .page-title-row {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-5); margin-bottom: var(--g-spacing-5);}
  .page-actions {width: 100%;}
  .page-actions > :last-child {flex: 1;}
  .page-description {font-size: 12px;}
  .stats-grid {gap: var(--g-spacing-2); margin-bottom: var(--g-spacing-5);}
  .stat-card {padding: var(--g-spacing-3);}
  .stat-top {font-size: 11px; gap: var(--g-spacing-1);}
  .stat-top svg {width: 15px;}
  .stat-bottom {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-1); margin-top: var(--g-spacing-2);}
  .stat-bottom > .g-text {font-size: 23px; line-height: 30px; letter-spacing: -1px;}
  .revenue-icon {display: none;}
  .stat-caption {font-size: 9px;}
  .table-tabs {padding: 0 var(--g-spacing-3); gap: var(--g-spacing-3); overflow-x: auto; min-height: 50px;}
  .table-tab.g-button {height: 50px; font-size: 12px;}
  .tab-count {display: none;}
  .table-toolbar {flex-direction: column; align-items: stretch; padding: var(--g-spacing-3); gap: var(--g-spacing-3);}
  .search-input {width: 100%;}
  .filter-controls {justify-content: space-between;}
  .filter-controls .g-select {flex: 1; min-width: 0;}
  .table-footer {flex-direction: column; padding: var(--g-spacing-4) var(--g-spacing-3);}
  .page-size {width: 100%;}
  .rows-summary {margin-left: auto;}
  .selection-bar {flex-wrap: wrap; gap: var(--g-spacing-2); padding: var(--g-spacing-3);}
  .selection-bar > span {width: 100%;}
  .workspace-footer {line-height: 1.5; font-size: 10px;}
}
